/**
 * The Cursor backend as the tools use it: launches go through the public
 * v1 Cloud Agents API (the only surface that takes per-launch `envVars`),
 * everything about an existing agent goes through the same
 * `aiserver.v1.BackgroundComposerService` RPCs Sand's CloudAgent tool
 * calls, so follow-ups queue, runs pause, and the full conversation is
 * readable. Both authenticate with the host's Cursor API key; the RPCs
 * exchange it for a session token the way the dashboard client does.
 */
import { randomUUID } from "node:crypto";
import * as z from "zod/v4";
import { CursorBackendClient } from "../../../internal/cursor/backend-client.js";
import { isRecord } from "../../../internal/is-record.js";
import { cloudAgentUrl, cursorBackendUrl, cursorExternalApiUrl, resolveApiKeySync, SIGN_IN_HINT, } from "../../../internal/cursor/credentials.js";
import { toModelSelection } from "../../../internal/sdk-runner.js";
import extension from "../extension.js";
const SERVICE = "BackgroundComposerService";
/** Launches and follow-ups from this extension carry the SDK source, like the v1 API. */
const SOURCE = "BACKGROUND_COMPOSER_SOURCE_SDK";
const RPC_TIMEOUT_MS = 60_000;
// The create call returns once the initial run exists, which can wait on a VM.
const LAUNCH_TIMEOUT_MS = 300_000;
export class CloudAgentsApiError extends Error {
    constructor(message, status) {
        super(message);
        this.status = status;
        this.name = "CloudAgentsApiError";
    }
}
// ---------------------------------------------------------------------------
// Proto-JSON response schemas (camelCase; default-valued fields are omitted)
// ---------------------------------------------------------------------------
const composerSchema = z.object({
    bcId: z.string(),
    name: z.string().optional(),
    status: z.string().optional(),
    isArchived: z.boolean().optional(),
    branchName: z.string().optional(),
    prUrl: z.string().optional(),
    linesAdded: z.number().optional(),
    linesRemoved: z.number().optional(),
    filesChanged: z.number().optional(),
});
const errorDetailsSchema = z.object({
    details: z.object({ title: z.string().optional(), detail: z.string().optional() }).optional(),
});
const infoResponseSchema = z.object({
    composer: z.object({
        composer: composerSchema,
        summary: z.string().optional(),
        startError: errorDetailsSchema.optional(),
        permanentError: errorDetailsSchema.optional(),
    }),
});
const toolResultSchema = z.object({
    toolName: z.string().optional(),
    args: z.string().optional(),
    rawArgs: z.string().optional(),
    content: z.string().optional(),
    error: z.object({ clientVisibleErrorMessage: z.string().optional() }).optional(),
});
const conversationResponseSchema = z.object({
    conversation: z
        .array(z.object({
        type: z.string().optional(),
        text: z.string().optional(),
        thinking: z.object({ text: z.string().optional() }).optional(),
        toolResults: z.array(toolResultSchema).optional(),
    }))
        .optional(),
});
const followupResponseSchema = z.object({ runId: z.string().optional() });
const environmentSchema = z.object({
    publicId: z.string(),
    name: z.string().optional(),
    repoConfig: z
        .object({ repos: z.array(z.object({ repoUrl: z.string().optional() })).optional() })
        .optional(),
});
const getEnvironmentResponseSchema = z.object({ environment: environmentSchema.optional() });
const listEnvironmentsResponseSchema = z.object({
    environments: z.array(environmentSchema).optional(),
});
function toCloudEnvironment(environment) {
    return {
        publicId: environment.publicId,
        name: environment.name ?? "",
        repoUrls: (environment.repoConfig?.repos ?? [])
            .map((repo) => repo.repoUrl ?? "")
            .filter((url) => url !== ""),
        eligible: true,
    };
}
const launchResponseSchema = z.object({
    agent: z.object({ id: z.string(), url: z.string().optional() }),
    run: z.object({ id: z.string(), status: z.string() }),
});
// ---------------------------------------------------------------------------
export class CloudAgentsBackend {
    constructor(apiKey, fetchImpl = fetch) {
        this.apiKey = apiKey;
        this.fetchImpl = fetchImpl;
        // The key is read per call: the host can sign in after the mount.
        this.rpcClient = new CursorBackendClient({
            backendUrl: cursorBackendUrl(),
            apiKey: "",
            getApiKey: apiKey,
            fetchImpl,
        });
    }
    /** `POST /v1/agents`: create the agent and start its first run in one call. */
    async launch(request) {
        const { cloud } = request;
        const body = {
            prompt: { text: request.prompt },
            name: request.name,
            model: request.model === undefined ? undefined : toModelSelection(request.model),
            env: cloud.env,
            envVars: cloud.envVars,
            mcpServers: cloud.mcpServers,
            teamMcpServers: cloud.teamMcpServers,
            repos: cloud.repos,
            workOnCurrentBranch: cloud.workOnCurrentBranch,
            autoCreatePR: cloud.autoCreatePR,
            skipReviewerRequest: cloud.skipReviewerRequest,
        };
        let response;
        try {
            response = await this.fetchImpl(`${cursorExternalApiUrl()}/v1/agents`, {
                method: "POST",
                headers: {
                    "content-type": "application/json",
                    authorization: `Bearer ${this.apiKey()}`,
                    "x-ghost-mode": "true",
                    "x-cursor-client-type": "agent-serve",
                    "x-request-id": randomUUID(),
                },
                body: JSON.stringify(body),
                signal: AbortSignal.timeout(LAUNCH_TIMEOUT_MS),
            });
        }
        catch (error) {
            throw new CloudAgentsApiError(`Cloud agent launch failed: ${error instanceof Error ? error.message : String(error)}`);
        }
        const text = await response.text();
        if (!response.ok) {
            throw new CloudAgentsApiError(`Cloud agent launch failed (${response.status}): ${apiErrorMessage(text)}`, response.status);
        }
        const parsed = launchResponseSchema.parse(JSON.parse(text));
        return {
            agentId: parsed.agent.id,
            runId: parsed.run.id,
            status: parsed.run.status.toLowerCase(),
            url: parsed.agent.url ?? cloudAgentUrl(parsed.agent.id),
        };
    }
    /** `GetEnvironment`: one saved environment by public id, or undefined when not visible. */
    async environment(publicId) {
        const { environment } = getEnvironmentResponseSchema.parse(await this.rpcClient.serviceRpc(SERVICE, "GetEnvironment", { publicId }, RPC_TIMEOUT_MS));
        return environment === undefined ? undefined : toCloudEnvironment(environment);
    }
    /**
     * `ListEnvironments`: the caller's visible environments whose display name
     * is exactly `name`. The v1 launch API resolves `env.name` by name, so this
     * is how a caller confirms the name picks one environment.
     */
    async environmentsNamed(name) {
        const { environments } = listEnvironmentsResponseSchema.parse(await this.rpcClient.serviceRpc(SERVICE, "ListEnvironments", { searchQuery: name, limit: 100 }, RPC_TIMEOUT_MS));
        return (environments ?? [])
            .filter((environment) => environment.name === name)
            .map(toCloudEnvironment);
    }
    async info(agentId) {
        const { composer } = infoResponseSchema.parse(await this.rpcClient.serviceRpc(SERVICE, "GetBackgroundComposerInfo", { bcId: agentId }, RPC_TIMEOUT_MS));
        const { composer: summary } = composer;
        const failure = composer.permanentError ?? composer.startError;
        return {
            agentId: summary.bcId,
            name: summary.name ?? "",
            status: statusOf(summary.status),
            archived: summary.isArchived === true,
            url: cloudAgentUrl(summary.bcId),
            branch: emptyToUndefined(summary.branchName),
            prUrl: emptyToUndefined(summary.prUrl),
            summary: emptyToUndefined(composer.summary),
            error: failureMessage(failure),
            changes: summary.filesChanged === undefined
                ? undefined
                : {
                    filesChanged: summary.filesChanged,
                    linesAdded: summary.linesAdded ?? 0,
                    linesRemoved: summary.linesRemoved ?? 0,
                },
        };
    }
    async conversation(agentId) {
        const { conversation } = conversationResponseSchema.parse(await this.rpcClient.serviceRpc(SERVICE, "GetBackgroundComposerConversation", { bcId: agentId }, RPC_TIMEOUT_MS));
        return (conversation ?? []).map((message) => {
            const toolCalls = (message.toolResults ?? []).map((result) => ({
                name: result.toolName ?? "",
                args: parseArgs(result.args ?? result.rawArgs),
                content: result.content,
                error: result.error?.clientVisibleErrorMessage,
            }));
            return {
                role: message.type === "MESSAGE_TYPE_HUMAN" ? "user" : "assistant",
                text: emptyToUndefined(message.text),
                thinking: emptyToUndefined(message.thinking?.text),
                toolCalls: toolCalls.length === 0 ? undefined : toolCalls,
            };
        });
    }
    /**
     * Queue a follow-up behind the current run, or with `interrupt` cancel the
     * in-flight step and run it now; the backend's `synchronous` switch.
     */
    async followUp(agentId, prompt, interrupt) {
        const { runId } = followupResponseSchema.parse(await this.rpcClient.serviceRpc(SERVICE, "AddAsyncFollowupBackgroundComposer", {
            bcId: agentId,
            synchronous: interrupt,
            followupSource: SOURCE,
            followupMessage: {
                text: prompt,
                type: "MESSAGE_TYPE_HUMAN",
                bubbleId: randomUUID(),
            },
        }, RPC_TIMEOUT_MS));
        return { runId };
    }
    async pause(agentId) {
        await this.rpcClient.serviceRpc(SERVICE, "PauseBackgroundComposer", { bcId: agentId, source: SOURCE }, RPC_TIMEOUT_MS);
    }
}
let backend;
/** The process-wide backend for this mount, built on first use. */
export function cloudAgentsBackend() {
    backend ??= new CloudAgentsBackend(apiKey);
    return backend;
}
export function apiKey() {
    const key = resolveApiKeySync({ apiKey: extension.config.apiKey });
    if (key === undefined) {
        throw new Error(`Cloud agents need a Cursor API key. ${SIGN_IN_HINT}`);
    }
    return key.apiKey;
}
function statusOf(status) {
    switch (status) {
        case "BACKGROUND_COMPOSER_STATUS_CREATING":
            return "creating";
        case "BACKGROUND_COMPOSER_STATUS_RUNNING":
            return "running";
        case "BACKGROUND_COMPOSER_STATUS_FINISHED":
            return "finished";
        case "BACKGROUND_COMPOSER_STATUS_ERROR":
            return "error";
        case "BACKGROUND_COMPOSER_STATUS_EXPIRED":
            return "expired";
        default:
            return "unknown";
    }
}
function failureMessage(failure) {
    const parts = [failure?.details?.title, failure?.details?.detail].filter((part) => part !== undefined && part !== "");
    return parts.length === 0 ? undefined : parts.join(": ");
}
function parseArgs(args) {
    if (args === undefined || args === "") {
        return undefined;
    }
    try {
        return JSON.parse(args);
    }
    catch {
        return args;
    }
}
function emptyToUndefined(value) {
    return value === undefined || value === "" ? undefined : value;
}
function apiErrorMessage(text) {
    try {
        const parsed = JSON.parse(text);
        const record = isRecord(parsed) ? parsed : undefined;
        const nested = record !== undefined && isRecord(record.error) ? record.error : undefined;
        const code = typeof nested?.code === "string"
            ? nested.code
            : record !== undefined && typeof record.code === "string"
                ? record.code
                : undefined;
        const message = typeof nested?.message === "string"
            ? nested.message
            : record !== undefined && typeof record.message === "string"
                ? record.message
                : undefined;
        return [code, message].filter((part) => part !== undefined).join(": ") || text;
    }
    catch {
        return text;
    }
}
